#!/usr/bin/env python3
"""Regenerates src/meson.build (the list of decompiled function sources)."""
from pathlib import Path

ROOT = Path(__file__).parent.parent.resolve()
SRC = ROOT / "src"

lines = [
    "# Generated by tools/gen_src_meson.py -- do not edit by hand.",
    "# One file per decompiled function, grouped by the binary it came from:",
    "#   arm9   -> the ARM9 main program",
    "#   ovNNN  -> overlay NNN",
    "",
    "tomo_coll_sources = files(",
]
count = 0
for target in sorted(p for p in SRC.iterdir() if p.is_dir()):
    for source in sorted(target.glob("func_*.c")):
        lines.append(f"    '{target.name}/{source.name}',")
        count += 1
lines.append(")")
(SRC / "meson.build").write_text("\n".join(lines) + "\n", encoding="utf-8")
print(f"src/meson.build: {count} sources")
